according_to(sec_1_section,first_player_wins,G) :- game(G),
first_player(G,Firstplayer),
throws(Firstplayer,Throws),
beats(Throws,Beats),
second_player(G,Secondplayer),
throws(Secondplayer,Throws2),
Beats = Throws2.

